require('dotenv').config({ path: require('path').join(__dirname, '../backend/.env') });

const path = require('path');
const fs = require('fs');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();

const MANIFEST_PATH = path.join(__dirname, '../shopify/shopify_upload_manifest.json');

// View keys as generated by pipeline.py / prompts.py VIEWS_BAG
const VIEWS = ['bag_front', 'bag_lifestyle', 'bag_flat', 'bag_detail'];

// One entry per color. productId is the zero-padded 6-digit ID from products.db.
// colorSlug must match the sanitized filename format: spaces → hyphens.
const PRODUCTS = [
  { color: 'Black',   colorSlug: 'Black',   colorHex: '#1A1A1A', productId: '000121' },
  { color: 'Natural', colorSlug: 'Natural', colorHex: '#F5F0E0', productId: '000130' },
];

function loadManifest() {
  return JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
}

function cdnUrl(manifest, productId, colorSlug, view) {
  const key = `${productId}_${colorSlug}_${view}.jpg`;
  const url = manifest[key];
  if (!url) throw new Error(`Manifest missing key: ${key}`);
  return url;
}

function toSlug(color) {
  return color.toLowerCase().replace(/\s+/g, '-');
}

async function main() {
  const manifest = loadManifest();

  // 1. Upsert "Bags" top-level category
  const bagsCategory = await prisma.category.upsert({
    where: { slug: 'bags' },
    update: {},
    create: {
      name: 'Bags',
      slug: 'bags',
      description: 'Custom printed tote bags and canvas bags',
      sortOrder: 8,
      isActive: true,
    },
  });
  console.log(`Category ready: ${bagsCategory.name} (${bagsCategory.id})\n`);

  for (const p of PRODUCTS) {
    const productName = `${p.color} Medium Cotton Canvas Tote Bag`;
    const productSlug = `${toSlug(p.color)}-medium-cotton-canvas-tote-bag`;
    const productSku = `TOTE-${p.colorSlug.toUpperCase()}`;

    console.log(`─── ${productName} ───`);

    // 2. Collect CDN URLs for all 4 views
    const imageUrls = {};
    for (const view of VIEWS) {
      imageUrls[view] = cdnUrl(manifest, p.productId, p.colorSlug, view);
    }

    // 3. Build ProductImage rows
    const productImages = VIEWS.map((view, idx) => ({
      url: imageUrls[view],
      alt: `${productName} — ${view.replace('bag_', '')} view`,
      sortOrder: idx,
    }));

    // 4. Build variant (tote bags are one-size)
    const variant = {
      color: p.color,
      colorHex: p.colorHex,
      colorDisplayName: p.color,
      size: 'One Size',
      sku: productSku,
      priceAdjustment: 0,
      stockQuantity: 300,
      imageUrl: imageUrls['bag_front'],
    };

    // 5. Delete existing product (to refresh images from new Codex-generated CDN URLs)
    const existing = await prisma.product.findUnique({ where: { slug: productSlug } });
    if (existing) {
      await prisma.productImage.deleteMany({ where: { productId: existing.id } });
      await prisma.variant.deleteMany({ where: { productId: existing.id } });
      await prisma.productCategory.deleteMany({ where: { productId: existing.id } });
      await prisma.product.delete({ where: { id: existing.id } });
      console.log(`  ↺ replaced: ${productSlug}`);
    }

    // 6. Create product with variant + images
    const created = await prisma.product.create({
      data: {
        name: productName,
        slug: productSlug,
        categoryId: bagsCategory.id,
        basePrice: 1999,
        sku: productSku,
        stockQuantity: 300,
        isActive: true,
        variants: { create: [variant] },
        images: { create: productImages },
        productCategories: { create: { categoryId: bagsCategory.id } },
      },
    });
    console.log(`  ✓ created: ${created.id}\n`);
  }

  console.log('All done.');
  await prisma.$disconnect();
}

main().catch(async (e) => {
  console.error(e);
  await prisma.$disconnect();
  process.exit(1);
});
